function compact(c:any){
 const lines=c.state.split('\n');
 const words=new Set((c.question+' '+c.options.join(' ')).toLowerCase().match(/[\p{L}\p{N}]{3,}/gu)?.filter((w:string)=>!['the','and','which','should','this','that','observed','control','from','current','page','with','for','before','after','button','link'].includes(w)) ?? []);
 const rank=lines.map((line:string,index:number)=>({index,line,score:[...words].reduce((sum,w)=>sum+(line.toLowerCase().includes(w)?1:0),0)+(index<2?100:0)})).sort((a:any,b:any)=>b.score-a.score||a.index-b.index);
 const selected:any[]=[];let length=0;
 for(const row of rank){if(!row.line.trim()||row.score===0||row.line.length>1600||length+row.line.length+1>1800)continue; selected.push(row);length+=row.line.length+1;}
 return selected.sort((a,b)=>a.index-b.index).map(row=>row.line).join('\n')+'\nState projection: '+c.state.length+' original characters, '+length+' selected. All candidate labels used equally; no expected index used.';
}
